// Record is an item as a line of an import gives it.
type Record struct {
	Line   int // the 1-based line of the text it came from
	ID     string
	Title  string
	Kind   string
	Copies int
}

// ParseRecords reads the items of text, one a line, as Import does.
func ParseRecords(text string) ([]Record, error) {
	var recs []Record
	for i, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		f := strings.Split(line, "|")
		if len(f) != 4 {
			return nil, fmt.Errorf("line %d: want 4 fields, got %d", i+1, len(f))
		}
		n, err := strconv.Atoi(strings.TrimSpace(f[3]))
		if err != nil {
			return nil, fmt.Errorf("line %d: copies: %v", i+1, err)
		}
		recs = append(recs, Record{Line: i + 1, ID: strings.TrimSpace(f[0]), Title: strings.TrimSpace(f[1]), Kind: strings.TrimSpace(f[2]), Copies: n})
	}
	return recs, nil
}

// ValidateRecords checks recs as Import does before it adds them to c.
func ValidateRecords(c *Catalog, recs []Record) error {
	seen := map[string]bool{}
	for _, r := range recs {
		if r.ID == "" {
			return fmt.Errorf("line %d: no id", r.Line)
		}
		if LoanDays(r.item()) == 0 {
			return fmt.Errorf("line %d: unknown kind %q", r.Line, r.Kind)
		}
		if r.Copies <= 0 {
			return fmt.Errorf("line %d: no copies", r.Line)
		}
		if _, there := c.Items[r.ID]; there || seen[r.ID] {
			return fmt.Errorf("line %d: %s is already there", r.Line, r.ID)
		}
		seen[r.ID] = true
	}
	return nil
}

// ApplyRecords adds recs to c.
func ApplyRecords(c *Catalog, recs []Record) {
	if c.Items == nil {
		c.Items = map[string]Item{}
	}
	for _, r := range recs {
		c.Items[r.ID] = r.item()
	}
}

func (r Record) item() Item {
	return Item{ID: r.ID, Title: r.Title, Kind: r.Kind, Copies: r.Copies}
}

recs, err := ParseRecords(text)
if err != nil {
	return err
}
if err := ValidateRecords(c, recs); err != nil {
	return err
}
ApplyRecords(c, recs)
return nil
